+    /// Benchmark-only cached-prefix preparation copied from the historical benchmark adapter.
+    #[doc(hidden)]
+    pub fn benchmark_prepare_cached_mtp_prefix(
+        &mut self,
+        prefix: &[u32],
+        chunk_ends: &[usize],
+    ) -> Result<()> {
+        let mut previous = 0;
+        for &end in chunk_ends {
+            if end <= previous || end > prefix.len() {
+                return Err(Error::Other("invalid benchmark prefix chunk boundary".into()));
+            }
+            previous = end;
+        }
+        if prefix.is_empty() || previous != prefix.len() {
+            return Err(Error::Other("benchmark chunks must cover the complete prefix".into()));
+        }
+        // Keep the same capacity-sized bank across all six cases. The pool
+        // allocator must not see a fresh growing checkpoint on every prepare.
+        let retained_cache = self.mtp_prompt_prefix_caches.pop_front();
+        self.configure_context_reuse(false)?;
+        self.runtime.reset(&self.ctx)?;
+        self.configure_context_reuse(true)?;
+        let options = GenerationOptions::greedy(1, None);
+        let mut start = 0;
+        for &end in chunk_ends {
+            self.benchmark_mtp_prefill_chunk(&prefix[start..end], &options)?;
+            start = end;
+        }
+        let mut cache = match retained_cache {
+            Some(mut cache) if cache.capacity >= self.runtime.target().capacity() => {
+                cache.tokens.clear();
+                cache
+            }
+            _ => self.take_mtp_prompt_prefix_cache(prefix.len())?,
+        };
+        self.runtime.capture_context(&self.ctx, &mut cache.snapshot)?;
+        cache.tokens.extend_from_slice(prefix);
+        self.mtp_prompt_prefix_caches.push_front(cache);
+        Ok(())
+    }
+
